-- HUD-USPS ZIP code to county crosswalk: one row per zip and quarter.
-- Uses the most recent load only; each file column is cast directly (no unpivot).
with src as (
    select * from {{ source('bronze', 'hud_usps_zip_county') }}
),

latest_load as (
