        cast(nullif(trim(geoid), '') as string) as county_fips,
        cast(nullif(trim(city), '') as string) as city,
        cast(nullif(trim(state), '') as string) as state,
        cast(nullif(trim(res_ratio), '') as decimal(38,30)) as res_ratio,
        cast(nullif(trim(bus_ratio), '') as decimal(38,30)) as bus_ratio,
        cast(nullif(trim(oth_ratio), '') as decimal(38,30)) as oth_ratio,
        cast(nullif(trim(tot_ratio), '') as decimal(38,30)) as tot_ratio,
        cast(nullif(trim(year), '') as int) as year,
        cast(nullif(trim(quarter), '') as int) as quarter,
        _source_file,
        _loaded_at
    from latest_load
)

